#include <stdio.h>
#include <stdlib.h>

int compare(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int T, N;
    scanf("%d%d", &T, &N);

    int x[10000];
    for (int i = 0; i < N; i++) {
        scanf("%d", &x[i]);
    }

    qsort(x, N, sizeof(int), compare);

    double minimum = T;
    for (int i = 0; i < N; i++) {
        double left = (i == 0) ? 0.0 : (x[i - 1] + x[i]) / 2.0;
        double right = (i == N - 1) ? (double)T : (x[i] + x[i + 1]) / 2.0;
        double neighborhood = right - left;
        if (neighborhood < minimum) {
            minimum = neighborhood;
        }
    }

    printf("%.2f\n", minimum);
    return 0;
}
